:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.question {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 24px;
  min-height: 2.5rem;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.answer,
.control {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 12px 24px;
  border: 3px solid var(--accent);
  border-radius: 6px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 80px;
}

.answer:hover:not(:disabled),
.control:hover {
  background: var(--accent);
  color: var(--bg);
}

.answer:focus-visible,
.control:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.answer:active:not(:disabled),
.control:active {
  transform: scale(0.95);
}

.answer:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-line {
  font-size: 1.25rem;
  margin-bottom: 24px;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: 700;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.control {
  font-size: 1rem;
  padding: 10px 20px;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .question { font-size: 1.5rem; }
  .answers { flex-direction: column; }
  .answer { width: 100%; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let current = 0;
let locked = false;

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function render() {
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  locked = false;
  scoreEl.textContent = String(score);
}

function handleAnswer(choice) {
  if (locked) return;
  locked = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[current].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (current < questions.length - 1) {
    current += 1;
    render();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  score = 0;
  current = 0;
  render();
});

render();
